    (2109101682588422145, '赣南脐橙 新鲜当季', '产地直发 坏果包赔', 2109101678394118155, 39.9, 50.7, 240, 1042, 'https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/000a8fefc04346acb4b1e891b142af4f.jpg', '["https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/000a8fefc04346acb4b1e891b142af4f.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/a10a648cffe34a578120d905fc56557b.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/1ee0c7c33ac04e23abf1cb693dcc8a73.jpg"]', '<p>【赣南脐橙 新鲜当季】产地直发 坏果包赔。产地直采，江西赣州发货，常温避光，保质期 30天。</p><p>采收后 24 小时内预冷分拣，全程冷链/保湿包装，坏果包赔；支持产地溯源批次查询。</p><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/a10a648cffe34a578120d905fc56557b.jpg" style="width:100%;display:block" /><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/1ee0c7c33ac04e23abf1cb693dcc8a73.jpg" style="width:100%;display:block" />', '江西赣州', '2026-09-07', '30天', '常温避光', 1, 90, 0),
    (2109101682588422146, '武鸣沃柑 薄皮蜜柑', '产地直发 现摘现发', 2109101678394118155, 25.9, 35.5, 500, 1298, 'https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/c891015e03db41f8889a750e07f03d22.jpg', '["https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/c891015e03db41f8889a750e07f03d22.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/7e46081cba024d4bb30ff0d3b966ca52.jpg", "https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/3aa55bbbf00f41dba99c5c6ba614f6ce.jpg"]', '<p>【武鸣沃柑 薄皮蜜柑】产地直发 现摘现发。产地直采，广西南宁发货，常温避光，保质期 30天。</p><p>采收后 24 小时内预冷分拣，全程冷链/保湿包装，坏果包赔；支持产地溯源批次查询。</p><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/7e46081cba024d4bb30ff0d3b966ca52.jpg" style="width:100%;display:block" /><img src="https://agsell-bucket.oss-cn-beijing.aliyuncs.com/product/image/20261011/3aa55bbbf00f41dba99c5c6ba614f6ce.jpg" style="width:100%;display:block" />', '广西南宁', '2026-08-09', '30天', '常温避光', 1, 80, 0),
