    (2097480000000004004, 0, 2109101682588422150, @demo_user, 1, '路上耽搁，到手有几颗发霉，失望。', -1, 0.0, '发霉,失望', 0, 0),
    (2097480000000004005, 0, 2109101682588422156, @demo_user, 5, '贵妃芒核小肉厚，很甜，物流也快。', 1, 1.0, '好吃,甜,快', 0, 0),
    (2097480000000004006, 0, 2109101682588422206, @demo_user, 5, '五常大米真的很香，煮饭满屋飘香，正宗！', 1, 1.0, '正宗,香', 0, 0),
    (2097480000000004007, 0, 2109101682588422206, @demo_user, 3, '米还行，但外袋有点破损。', -1, 0.3, '破损,还行', 0, 0),
    (2097480000000004008, 0, 2109101682588422175, @demo_user, 5, '西兰花非常新鲜，口感脆嫩，会回购。', 1, 1.0, '新鲜,回购,脆,嫩', 0, 0),
    (2097480000000004009, 0, 2109101682588422175, @demo_user, 2, '有几朵发黄，不太新鲜。', -1, 0.0, '不新鲜,失望', 0, 0),
    (2097480000000004010, 0, 2109101682588422239, @demo_user, 5, '土鸡蛋蛋黄颜色深，炒出来很香。', 1, 1.0, '新鲜,香', 0, 0),
    (2097480000000004011, 0, 2109101682588422331, @demo_user, 5, '湘西腊肉烟熏味正，就是稍微咸了点。', 1, 1.0, '正宗,咸', 0, 0);
